public static void generateCompleteBipartiteGraph(Graph<V,E> target, Map<String,V> resultMap) {

    // Partition the vertices into two sets
    Set<V> setA = new HashSet<>();
    Set<V> setB = new HashSet<>();
    for (V v : target.vertexSet()) {
        if (setA.size() <= setB.size()) {
            setA.add(v);
        } else {
            setB.add(v);
        }
    }

    // Add edges between vertices in the same set
    for (V v : setA) {
        for (V w : setA) {
            if (v != w) {
                target.addEdge(v, w);
            }
        }
    }
    for (V v : setB) {
        for (V w : setB) {
            if (v != w) {
                target.addEdge(v, w);
            }
        }
    }

    // Add edges between vertices from different sets
    for (V v : setA) {
        for (V w : setB) {
            if (!target.containsEdge(v, w)) {
                target.addEdge(v, w);
            }
        }
    }

    // Populate the result map
    for (V v : target.vertexSet()) {
        resultMap.put(v.toString(), v);
    }
}

