    Preconditions.checkArgument(dayStep > 0, "Invalid day step: " + dayStep);
    Preconditions.checkArgument(timeBucket > 0, "Invalid time bucket: " + timeBucket);

    // Calculate the number of digits in the time bucket
    int numDigits = (int) Math.log10(timeBucket) + 1;

    // Check if the time bucket is already in the compressed format
    if (numDigits == dayStep) {
        return timeBucket;
    }

    // Calculate the new time bucket by removing the trailing zeros
    long newTimeBucket = timeBucket / Math.pow(10, numDigits - dayStep);
    newTimeBucket = newTimeBucket * Math.pow(10, dayStep);

    return newTimeBucket;
}

