private void pop(String descriptor) {
    // Parse the descriptor to determine the types of the arguments that need to be popped
    Type[] argTypes = typeFromDescriptor(descriptor);

    // Pop the argument types from the output frame stack
    for (Type argType : argTypes) {
        Stack<Object> stack = getStack(argType);
        Object arg = stack.pop();
        // Check if the argument type is a method type and if so, pop its return type as well
        if (argType instanceof MethodType) {
            stack = getStack(((MethodType) argType).getReturnType());
            stack.pop();
        }
    }
}

void pop(final String descriptor) {
    AbstractType[] types = new AbstractType[descriptor.count('(') + 1];
    boolean isMethod = false;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == '(') {
            isMethod = true;
        } else if (c == ')') {
            isMethod = false;
        } else if (c == ';') {
            if (isMethod) {
                types[types.length - 1] = AbstractType.Method;
            } else {
                types[types.length - 1] = AbstractType.Primitive;
            }
        }
    }
    for (AbstractType type : types) {
        AbstractElement element = pop();
        if (type.equals(AbstractType.Primitive)) {
            checkPrimitiveType(element.getType());
        } else if (type.equals(AbstractType.Method)) {
            checkMethodType(element.getType());
        }
    }
}

