public int writeTo(final LinkedBuffer node, final DataOutput out) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // Write the current node to the output stream
        out.write(node.data, 0, node.size);
        totalSize += node.size;
        // Advance to the next node
        node = node.next;
    }
    return totalSize;
}

public int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }

    int totalLen = 0;
    while (node != null) {
        out.write(node.getBuffer(), 0, node.getLength());
        totalLen += node.getLength();
        node = node.getNextNode();
    }

