public void readFrom(final InputStream in) throws IOException {
    buffer.clear();
    int readBytes = 0;
    while (readBytes < bufferSize) {
        final int maxBytesToRead = Math.min(bufferSize - readBytes, DEFAULT_CHUNK_SIZE);
        int bytesRead = in.read(buffer, readBytes, maxBytesToRead);
        if (bytesRead < 0) {
            throw new EOFException("Could not read beyond the end of the InputStream");
        }
        readBytes += bytesRead;
    }
    buffer.rewind();
}

public void readFrom(final InputStream in) throws IOException {
    // Clear the buffer
    buffer.clear();

    // Read from the input stream and fill the buffer
    int numBytes = in.read(buffer.array());

    // If the number of bytes read is less than the capacity of the buffer, then
    // the input stream has been fully read and the buffer is ready to be used
    if (numBytes < buffer.capacity()) {
        // Set the limit to the last valid byte read
        buffer.limit(numBytes);
    } else {
        // The buffer is full and the read pointer is at the end of the buffer
        buffer.limit(buffer.capacity());
    }
}

public void readFrom(final InputStream in) throws IOException {
    /* Clear and fill the buffer of this ClassFileBuffer with the supplied byte stream. The read pointer is reset to the start of the byte array. */
    byte[] buffer = new byte[4096];
    int numBytesRead = 0;

    /* Loop until at least 1 byte is read from the input stream */
    while (numBytesRead < 1) {
        int bytesRead = in.read(buffer);
        if (bytesRead < 0) {
            throw new EOFException("The supplied input stream does not contain enough data.");
        }
        numBytesRead += bytesRead;
    }

    /* Reset the buffer pointer to the start of the buffer */
    this.bufferPointer = 0;

    /* Fill the buffer with the read bytes */
    System.arraycopy(buffer, 0, this.buffer, 0, numBytesRead);
}

