   while (read_pointer < BUFFER_SIZE) {
      int amountRead = in.read(array, read_pointer, BUFFER_SIZE-read_pointer);
      if (amountRead < 0) {
         throw new EOFException("End of file reached prematurely");
      }
      read_pointer += amountRead;
   }

