public static Object convertToType(Class<?> type, Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("type cannot be null");
    }
    if (value == null) {
        return null;
    }
    if (type.isInstance(value)) {
        return value;
    }
    if (type == Character.class || type == Character.TYPE) {
        if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() != 1) {
                throw new IllegalArgumentException("Value must be a single character string");
            }
            return strValue.charAt(0);
        } else if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        } else {
            throw new IllegalArgumentException("Value must be a String or Number");
        }
    } else {
        throw new IllegalArgumentException("Cannot convert value to type " + type.getName());
    }
}

