private String unescapeId(String input) {
    if (input == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i == input.length() - 1) {
                throw new IllegalArgumentException("Input ends with an orphaned escape character");
            }
            c = input.charAt(i + 1);
            if (c == 't') {
                result.append('\t');
            } else if (c == 'n') {
                result.append('\n');
            } else if (c == 'r') {
                result.append('\r');
            } else if (c == 'f') {
                result.append('\f');
            } else if (c == 'b') {
                result.append('\b');
            } else if (c == 'u') {
                if (i + 4 >= input.length()) {
                    throw new IllegalArgumentException("Input ends with an incomplete unicode escape sequence");
                }
                String hex = input.substring(i + 2, i + 6);
                char[] chars = hex.toCharArray();
                int codepoint = Integer.parseInt(new String(chars), 16);
                result.append(Character.toChars(codepoint));
                i += 4;
            } else {
                result.append(c);
            }
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

private String unescapeId(String input) {
    StringBuilder output = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        switch (c) {
            case '\\': i++; output.append(unescapeOctalSequence(input, i)); break;
            case '\'': output.append('"'); break;
            case '"': output.append('"'); break;
            default: output.append(c);
        }
    }
    return output.toString();
}

private String unescapeOctalSequence(String input, int index) {
    StringBuilder octal = new StringBuilder(3);
