/**
 * Reverses the order of the elements in the specified range within the given array.
 * @param arr the array
 * @param from the index of the first element (inclusive) inside the range to reverse
 * @param to the index of the last element (inclusive) inside the range to reverse
 * @return void
 */
 public static final <V>void reverse(V[] arr, int from, int to) {
      // Base case: if the range is empty, return
      if (from > to) {
           return;
      }

      // Recursive case: swap the first and last elements, and then recursively swap the remaining elements
      V temp = arr[from];
      arr[from] = arr[to];
      arr[to] = temp;

      // Recursively reverse the remaining elements
      reverse(arr, from + 1, to - 1);
 }

public static void reverse(Object[] arr, int from, int to) {
     while (from < to) {
        Object temp = arr[from];
        arr[from++] = arr[to];
        arr[to--] = temp;
     }
}

