    int loc0 = 0;
    for (int loc1 = 0; loc1 < arr.length; loc1++) {
        if (arr[loc1] == from) {
            reverse(arr, loc0, loc1);
            loc0 = ++loc1;
        }
    }
    reverse(arr, loc0, arr.length);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

