    }
    return separators;
}

private List<Pair<Integer, Integer>> computeLocalSeparators(V vertex, E edge) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (E incidentEdge : graph.getEdges(vertex, edge)) {
        separators.addAll(computeIndividualSeparators(incidentEdge, vertex));
    }
    return separators;
}

private List<Pair<Integer, Integer>> computeIndividualSeparators(E incidentEdge, V vertex) {
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (V neighbor : graph.getNeighborhood(vertex, incidentEdge)) {
        if (neighbor != vertex) {
            separators.add(new Pair<>(vertex, neighbor));
        }
    }
    return separators;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E edge : graph.edgeSet()) {
