        separatorList.add(new Pair<>(separators, edge));
    }
    return separatorList;
}

private List<Pair<Integer, Integer>> computeSeparatorsForEdge(E edge) {
    V source = graph.getEdgeSource(edge);
    V target = graph.getEdgeTarget(edge);
    List<Pair<Integer, Integer>> separators = new ArrayList<>();
    for (V vertex : graph.vertexSet()) {
        if (vertex != source && vertex != target) {
            List<Pair<Integer, Integer>> localSeparators = computeLocalSeparatorsInNeighborhood(vertex, edge);
            separators.addAll(localSeparators);
        }
    }
    return separators;
}

private List<Pair<Integer, Integer>> computeLocalSeparatorsInNeighborhood(V vertex, E edge) {
    List<Pair<Integer, Integer>> localSeparators = new ArrayList<>();
    for (E neighborEdge : graph.edgesOf(vertex)) {
        if (graph.getEdgeSource(neighborEdge) == vertex) {
            localSeparators.add(new Pair<>(vertex, graph.getEdgeTarget(neighborEdge)));
        }
    }
    return localSeparators;
}

