public static Type resolveBound(TypeVariable<?> typeVariable){
    Type firstBound = typeVariable.getBounds()[0];
    if(firstBound instanceof Class){
        return firstBound;
    }
    return Unknown.class;
}

private static final Type resolveBound(TypeVariable<?> typeVariable) {
    Class<?> variableClass = typeVariable.getClass();
    for (Class<?> clazz = variableClass; clazz != null; clazz = clazz.getSuperclass()) {
        for (Field field : clazz.getDeclaredFields()) {
            if (!Modifier.isStatic(field.getModifiers())) continue;
            Type type = (Type) field.get(null);
            if (!(type instanceof TypeVariable)) continue;
            if (type == typeVariable) {
                if (Modifier.isFinal(field.getModifiers())) {
                    return Unknown.class;
                }
                return field.getGenericType();
            }
        }
    }
    return Unknown.class;
}

private static final ParameterizedType createParameterizedType(Class<?> rawClass, List<Type> typeArgs) {
    Type[] typeArguments = new Type[typeArgs.size()];
    int i = 0;
    for (Type typeArg : typeArgs) {
        if (typeArg instanceof WildcardType) {
            // Resolve the bound type of the wildcard and assign it to the type argument
            Type boundType = resolveBound(((WildcardType) typeArg).getTypeParameter());
            typeArguments[i] = boundType;
        } else {
            typeArguments[i] = typeArg;
        }
        i++;
    }
    return new ParameterizedTypeImpl(rawClass, typeArguments, null);
}

Type resolveBound(TypeVariable<?> typeVariable) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0) {
        return Unknown.class;
    }
    return bounds[0];
}

