    for (K key : keys) {
        int upperBound = 0;
        for (K k : keys) {
            if (key <= k) {
                upperBound++;
            }
        }
        upperBounds.add(upperBound);
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        int upperBound = key.intValue();
        upperBound = Math.min(upperBound, maxValue);
        upperBounds.add(upperBound);
    }
    return upperBounds;
}

List<Integer> computeUpperBounds(List<K> keys) {
        if (keys == null) {
            throw new IllegalArgumentException("keys list cannot be null");
        } else if (keys.isEmpty()) {
            return Collections.emptyList();
        }
        List<Integer> upperBounds = new ArrayList<>();
        for (K key : keys) {
            int upperBound = key + 1;
            if (upperBound == Integer.MAX_VALUE) {
                throw new IllegalArgumentException("upper bound cannot exceed Integer.MAX_VALUE");
            }
            upperBounds.add(upperBound);
        }
        return upperBounds;
    }

