public static String applyRelativePath(String path, String relativePath) {
    // Calculate the new path by concatenating the relative path and the original path
    String newPath = path + relativePath;

    // Remove any duplicate forward slashes
    newPath = newPath.replaceAll("/+", "/");

    return newPath;
}

public static String applyRelativePath(String path, String relativePath) {
    StringBuilder result = new StringBuilder(path);
    for (String component : relativePath.split("/")) {
        if (component.equals("..")) {
            // If the component is "..", then remove the last component from the result
            int lastSeparatorIndex = result.lastIndexOf("/");
            if (lastSeparatorIndex != -1) {
                result.delete(lastSeparatorIndex, result.length());
            }
        } else if (!component.isEmpty()) {
            // If the component is not "..", then add it to the result
            if (result.charAt(result.length() - 1) != '/') {
                result.append("/");
            }
            result.append(component);
        }
    }
    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    String result = path;
    String[] relativePathSegments = relativePath.split("/");
    for (String segment : relativePathSegments) {
        if (segment.equals("..")) {
            result = result.substring(0, result.lastIndexOf('/'));
        } else if (!segment.equals("")) {
            result += '/' + segment;
        }
    }
    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new NullPointerException();
    }
    String[] pathParts = path.split("/");
    String[] relPathParts = relativePath.split("/");
    if (pathParts.length == 0 || relPathParts.length == 0) {
        throw new IllegalArgumentException("Invalid path or relative path");
    }
    String newPath = pathParts[0];
    for (int i = 1; i < pathParts.length; i++) {
        newPath = newPath + "/" + pathParts[i];
    }
    for (String relPart : relPathParts) {
        if (relPart.equals(".")) {
            continue;
        } else if (relPart.equals("..")) {
            newPath = newPath.substring(0, newPath.lastIndexOf('/'));
        } else {
            newPath = newPath + "/" + relPart;
        }
    }
    return newPath;
}

