    if (filename == null) {
        return -1;
    }
    int lastUnixPos = indexOfLastSeparator(filename);
    int lastWindowsPos = filename.lastIndexOf("\\");
    int lastPos = Math.max(lastUnixPos, lastWindowsPos);
