public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastSeparatorPos = indexOfLastSeparator(filename);
    if (lastSeparatorPos < 0) {
        return -1;
    }
    int pos = filename.lastIndexOf('.', lastSeparatorPos);
    if (pos == 0) {
        return -1;
    } else if (pos < 0) {
        return filename.length();
    } else {
        return pos;
    }
}

