public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (var reader = new BufferedReader(new FileReader(file))) {
      ProfileAnalyzeTimeRange currentTimeRange = null;
      String line;
      while ((line = reader.readLine()) != null) {
        if (line.startsWith("[ThreadSnapshot")) {
          int indexOfBrace = line.indexOf("{");
          String[] threadSnapshotInfo = line.substring(indexOfBrace + 1).split(",");
          ThreadSnapshot threadSnapshot = new ThreadSnapshot(
              Long.parseLong(threadSnapshotInfo[0]), // thread id
              Long.parseLong(threadSnapshotInfo[1]), // effectiveTimestamp
              Long.parseLong(threadSnapshotInfo[2]), // processorCount
              Integer.parseInt(threadSnapshotInfo[3]) // numStackFrames
          );
          if (currentTimeRange == null || !currentTimeRange.isInInclusiveRange(threadSnapshot.getEffectiveTimestamp())) {
            currentTimeRange = findMatchingTimeRange(timeRanges, threadSnapshot.getEffectiveTimestamp());
          }
          if (currentTimeRange != null && currentTimeRange.isInInclusiveRange(threadSnapshot.getEffectiveTimestamp())) {
            threadSnapshots.add(threadSnapshot);
          }
        }
      }
    }
    return threadSnapshots;
  }

public static ProfileAnalyzeTimeRange findMatchingTimeRange(List<ProfileAnalyzeTimeRange> timeRanges, long timestamp) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
      if (timeRange.isInInclusiveRange(timestamp)) {
        return timeRange;
      }
    }
    return null;
  }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    if (file == null || !file.exists()) {
        throw new IOException("File is null or does not exist");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IOException("Time ranges are null or empty");
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            if (tokens.length != 5) {
                throw new IOException("Invalid input file");
            }

            long timestamp = Long.parseLong(tokens[0]);

            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                    ThreadSnapshot snapshot = new ThreadSnapshot();
                    snapshot.setTimestamp(timestamp);
                    snapshot.setThreadName(tokens[1]);
                    snapshot.setStackTrace(tokens[2]);
                    snapshot.setStartTime(Long.parseLong(tokens[3]));
                    snapshot.setEndTime(Long.parseLong(tokens[4]));
                    snapshots.add(snapshot);
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Could not read input file", e);
    }

    return snapshots;
}

void loadThreadSnapshotsInAppointingTimeRange(String filePath, long startTime, long endTime) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.matches(".*</NaiveProfileTree>")) {
                continue;
            }

            String[] parts = line.split("\t");
            int threadId = Integer.parseInt(parts[0]);
            long threadCPUTime = Long.parseLong(parts[1]);
            long threadFreq = Long.parseLong(parts[2]);
            long threadPauseTime = Long.parseLong(parts[3]);
            long threadWallClock = Long.parseLong(parts[4]);
            long subtreeTime = Long.parseLong(parts[5]);

            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadCPUTime, threadFreq, threadPauseTime, threadWallClock, subtreeTime);
            threadSnapshots.add(threadSnapshot);
        }
    } catch (IOException e) {
